private void solve(final FastIO io, final String[] args) {
    io.setAutoFlush(false);
    io.setAutoOutFlush(false);

    int Q = io.nextInt();
    while (Q-- > 0) {
        int X = io.nextInt();
        int n = 0;
        for (int i = 0; i < 100; ++i) {
            if (test(i) % 100 == X % 100) {
                n = i;
                break;
            }
        }
        for (int i = 2; i < 9; ++i) {
            int d = (int) Math.pow(10, i);
            int d2 = d * 10;
            for (int j = 0; j < 10; ++j) {
                int n2 = n + d * j;
                if (test(n2) % d2 == X % d2) {
                    n = n2;
                    break;
                }
            }
        }
        io.println(test(n) == X ? n : -1);
    }
}

private int test(int n) {
    long result = 1;
    long base = n;
    int mod = 1000000000;
    for (int i = 0; i < n; i++) {
        result = (result * base) % mod;
    }
    return (int) result;
}
